import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;

import com.wolinski.shop.money.Money;
import com.wolinski.shop.orders.api.OrderSummary;
import com.wolinski.shop.shipping.api.CarrierGateway;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.Test;

class OrderServiceTest {

    private final List<String> booked = new ArrayList<>();

    private final CarrierGateway fakeCarrier = orderId -> {
        booked.add(orderId);
        return "TRK-" + orderId;
    };

    private OrderService service(CarrierGateway carrier) {
        return new OrderService(new OrderRepository(), carrier);
    }

    @Test
    void confirmBooksAShipmentAndStoresTheTrackingNumber() {
        OrderService orders = service(fakeCarrier);
        String id = orders.place("c-1", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));

        assertNull(orders.summary(id).trackingNumber());

        orders.confirm(id);

        OrderSummary summary = orders.summary(id);
        assertEquals(List.of(id), booked);
        assertEquals("CONFIRMED", summary.status());
        assertEquals("TRK-" + id, summary.trackingNumber());
    }

    @Test
    void aFailedBookingLeavesTheOrderUnconfirmed() {
        CarrierGateway failing = orderId -> {
            throw new IllegalStateException("carrier down");
        };
        OrderService orders = service(failing);
        String id = orders.place("c-1", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));

        assertThrows(IllegalStateException.class, () -> orders.confirm(id));

        OrderSummary summary = orders.summary(id);
        assertEquals("PLACED", summary.status());
        assertNull(summary.trackingNumber());
    }
}
}
